package au.aumanet.app;
import java.io.*;import java.nio.file.*;import java.security.*;import org.json.*;
/** Exact GroupIdentity signer with a real test private key replacing Android Keystore only. */
public final class NodeUpdateSigningTest{
 static int assertions;static void check(boolean b){assertions++;if(!b)throw new AssertionError("Update signer domain/scope regression");}interface Task{void run()throws Exception;}static void denies(Task task)throws Exception{boolean rejected=false;try{task.run();}catch(Exception expected){rejected=true;}check(rejected);}
 public static void main(String[]args)throws Exception{NodeUpdateHostTest.setup(new File(args[0]));KeyPair owner=NodeUpdateHostTest.owner;NodeUpdateSigningHarness h=new NodeUpdateSigningHarness(owner);NodeUpdateCodec.Message q=NodeUpdateHostTest.query();byte[] signature=h.signGatewayUpdate(q,q.group,q.epoch,q.target,q.relay);NodeReleaseManifest.verify(owner.getPublic(),NodeUpdateCodec.DOMAIN,q.body,signature);check(true);denies(()->h.signGatewayUpdate(q,q.group,2,q.target,q.relay));denies(()->h.signGatewayUpdate(q,q.group,1,"9".repeat(32),q.relay));NodeUpdateCodec.Message wrong=NodeUpdateCodec.query(q.target,q.group,1,"9".repeat(64),q.relay,q.challenge);denies(()->h.signGatewayUpdate(wrong,q.group,1,q.target,q.relay));NodeUpdateCodec.Message report=NodeUpdateHostTest.report(q,NodeUpdateCodec.ephemeral(),0,"0".repeat(32),"0".repeat(64),0);denies(()->h.signGatewayUpdate(report,q.group,1,q.target,q.relay));NodeUpdateCodec.Message forgedStart=NodeUpdateCodec.start(report,NodeUpdateCodec.ephemeral(),NodeUpdateHostTest.release);denies(()->h.signGatewayUpdate(forgedStart,q.group,1,q.target,q.relay));JSONObject vector=new JSONObject(Files.readString(Path.of(args[1])));NodeReleaseManifest trusted=NodeReleaseManifest.checked(NodeReleaseManifest.base64(vector.getString("manifest"),384),NodeReleaseManifest.base64(vector.getString("signature"),72));NodeUpdateCodec.Message start=NodeUpdateCodec.start(report,NodeUpdateCodec.ephemeral(),trusted);signature=h.signGatewayUpdate(start,q.group,1,q.target,q.relay);NodeReleaseManifest.verify(owner.getPublic(),NodeUpdateCodec.DOMAIN,start.body,signature);check(true);NodeUpdateCodec.Message command=NodeUpdateCodec.command(report,"8".repeat(32),trusted.id,1);signature=h.signGatewayUpdate(command,q.group,1,q.target,q.relay);NodeReleaseManifest.verify(owner.getPublic(),NodeUpdateCodec.DOMAIN,command.body,signature);check(true);System.out.println(new JSONObject().put("status","pass").put("testCount",1).put("assertionCount",assertions));}
}
